/* ==UserCSS==
@name           Darken Backgrounds by 60%
@namespace      http://userstyles.org
@version        1.0
@description    Darkens all element backgrounds by 60%.
@author         Your Name
@preprocessor   stylus
==/UserCSS== */

* {
  background-color: rgba(0, 0, 0, 0) !important;
}

/* Darken backgrounds */
* {
  background-color: color-mod(var(--original-bg, white) shade(60%)) !important;
}
